package dev.minecraftvideoplayer.web;
public final class AdminPage {
 private AdminPage(){}
 public static final String HTML="""<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Video Player Admin</title><style>body{font:14px system-ui;background:#0b0d12;color:#eee;max-width:800px;margin:auto;padding:24px}section{background:#151923;border:1px solid #303747;border-radius:12px;padding:16px;margin:12px 0}button,input{padding:10px;border-radius:8px;border:1px solid #394150;background:#0b0d12;color:#fff}button{cursor:pointer}</style></head><body><h1>Video Player Admin</h1><section><input id="token" type="password" placeholder="Admin token"><button onclick="save()">Save token</button><pre id="status">Not connected.</pre></section><section><button onclick="rotate()">Rotate YouTube API key</button> <button onclick="saveData()">Save library</button></section><script>const $=id=>document.getElementById(id);function t(){return localStorage.mvpAdminToken||$('token').value}function save(){$('token').value&&(localStorage.mvpAdminToken=$('token').value);load()}async function call(p,o={}){let s=localStorage.mvpAdminToken||$('token').value;let r=await fetch(p+'?token='+encodeURIComponent(s),o);return r.json()}async function load(){try{$('status').textContent=JSON.stringify(await call('/api/admin/status'),null,2)}catch(e){$('status').textContent='Connection failed'}}async function rotate(){await call('/api/admin/rotate-key',{method:'POST'});load()}async function saveData(){await call('/api/admin/save',{method:'POST'});load()}load()</script></body></html>""";
}